# Components that are *not* the line (a part of a total): left unmapped on purpose, so a part is never taken for the whole.
COMPONENTS = ["Cost of services", "Selling and marketing expenses", "General and administrative expenses", "Net system sales", "Cost of system sales"]


def test_every_line_has_wording_that_maps_to_it_and_nothing_is_left_out():
    assert set(VARIANTS) | {"net_income_attributable"} == set(canonical.METRICS), set(canonical.METRICS) ^ (set(VARIANTS) | {"net_income_attributable"})
    miss = [(c, label, (taxonomy.get("ifrs").match(label).code if taxonomy.get("ifrs").match(label) else None)) for c, labels in VARIANTS.items() for label in labels
            if not taxonomy.get("ifrs").match(label) or taxonomy.get("ifrs").match(label).code != c]
    assert not miss, miss
    assert all(taxonomy.get("ifrs").match(c) is None for c in COMPONENTS)


def test_proceeds_and_look_alike_phrases_are_not_taken_for_the_line():
    m = taxonomy.get("ifrs")
    for label in ("Proceeds from sale of property, plant and equipment", "Depreciation of right-of-use lease liability", "Net cash used in operating activities of discontinued segment x",
                  "Dividends payable", "Repurchase agreements", "Interest income", "Long-term debt rating"):
        r = m.match(label)
        assert r is None or r.code not in ("capital_expenditure", "depreciation_amortization", "operating_cash_flow", "dividends_paid", "share_repurchases", "interest_expense", "long_term_debt"), (label, r)


