        ("Accounts payable", [rl.n(120), rl.n(110)]), ("Short-term borrowings", [rl.n(50), rl.n(60)]), ("Total current liabilities", [rl.n(270), rl.n(250)]), ("Long-term debt, net of current portion", [rl.n(400), rl.n(420)]),
